(()=>{const t=async(t,e)=>{const o=document.getElementById(t);if(o)try{const t=await fetch(e);if(!t.ok)throw new Error(`Failed to load ${e}: ${t.status} ${t.statusText}`);o.innerHTML=await t.text()}catch(t){console.error(t)}};document.addEventListener("DOMContentLoaded",()=>{const e=(()=>{const t=window.location.pathname.split("/").filter(Boolean),e=Math.max(t.length-1,0);return`${"../".repeat(e)}components/`})();t("site-nav",`${e}nav.html`),t("site-footer",`${e}footer.html`)})})();